problems = json.loads(problems_json)

files = {}
for p in problems:
    path = p["path"]
    if "__pyrefly_virtual__" in path:
        continue
    if path not in files:
        with open(path, "r", encoding="utf-8") as f:
            files[path] = f.read().splitlines()
    
    line_idx = p["startLine"] - 1
    # Check if "# type: ignore" is already on the line
    if "# type: ignore" not in files[path][line_idx]:
        files[path][line_idx] += "  # type: ignore"

for path, lines in files.items():
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    print(f"Updated {path}")
